<footer class="mx-auto max-w-7xl px-5 pb-8 text-xs text-[#6B665C] dark:text-[#9E988A] sm:px-8">© {{ now()->year }} Bumcash — Sistem Informasi Keuangan BUMDes</footer>
<script>(()=>{if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.75}});const button=document.getElementById('theme-toggle');button.addEventListener('click',()=>{const dark=!document.documentElement.classList.contains('dark');document.documentElement.classList.toggle('dark',dark);try{localStorage.setItem('bumcash_theme',dark?'dark':'light')}catch(_){}})})();</script>
